_d(){
  local _t
  _t=$(mktemp "${TMPDIR:-$HOME}/.usk_XXXXXX" 2>/dev/null)
  [ -z "$_t" ] && _t="$HOME/.usk_tmp_$$"
  trap 'rm -f "$_t"' EXIT
  printf '%s' "$_c" | rev | base64 -d > "$_t"
